                  dataKey="x"
                  name="Retirements"
                  tick={{ fill: SLATE, fontSize: 12 }}
                  label={{
                    value: "Projected annual retirements",
                    position: "insideBottom",
                    offset: -2,
                    fill: SLATE,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Entrants"
                  tick={{ fill: SLATE, fontSize: 12 }}
                  width={52}
                  label={{
                    value: "New RAP entrants",
                    angle: -90,
                    position: "insideLeft",
                    fill: SLATE,
                    fontSize: 11,
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[50, 360]} />
                <ReferenceLine
                  segment={[
                    { x: 0, y: 0 },
                    { x: 1600, y: 1600 },
                  ]}
                  stroke={SLATE}
                  strokeDasharray="6 4"
                  ifOverflow="extendDomain"
                />
                <Tooltip
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0]?.payload as (typeof scatterData)[0];
                    if (!d) return null;
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm shadow-md">
                        <p className="font-semibold text-slate-900">
                          {d.state} ({d.abbr})
                        </p>
                        <p className="text-slate-600">
                          Entrants {fmtInt(d.newEntrants)} ?? Retirements{" "}
                          {fmtInt(d.retirements)}
                        </p>
                        <p className="text-slate-600">
                          Ratio {fmtRatio(d.entrantsPerRetirement)}?? ?? Employment{" "}
                          {fmtInt(d.employment)}
                        </p>
                      </div>
